// Vapi araması başlatılamadıysa: lead'i kısa süre sonra tekrar denenecek şekilde işaretle
const A = $('AYARLAR').first().json;
const F = A.ALAN;
const simdi = new Date();
const cmd = {};
const olaylar = [];

$input.all().forEach((item, i) => {
